-- 创建第1个测试账本：家庭账本
INSERT INTO ledgers (name, type, description, ownerId, createdAt, updatedAt, isArchived)
VALUES ('家庭账本', 'family', '家庭日常开支记录', 4200293, NOW(), NOW(), 0);

SET @ledger1_id = LAST_INSERT_ID();

-- 为账本1添加成员记录（使用正确的字段名）
INSERT INTO ledger_members (ledgerId, userId, role, nickname, memberType)
VALUES (@ledger1_id, 4200293, 'owner', '胡', 'real');

-- 创建第2个测试账本：生意账本
INSERT INTO ledgers (name, type, description, ownerId, createdAt, updatedAt, isArchived)
VALUES ('生意账本', 'business', '公司业务收支记录', 4200293, NOW(), NOW(), 0);

SET @ledger2_id = LAST_INSERT_ID();

-- 为账本2添加成员记录
INSERT INTO ledger_members (ledgerId, userId, role, nickname, memberType)
VALUES (@ledger2_id, 4200293, 'owner', '胡', 'real');

-- 查询创建的账本
SELECT l.id, l.name, l.type, l.ownerId, lm.role, lm.nickname
FROM ledgers l
LEFT JOIN ledger_members lm ON l.id = lm.ledgerId
ORDER BY l.id;

